    m.Width = 0; m.Height = 0; m.Size.X = 40.0f; m.Size.Y = 20.0f;
    m.Position.X = 100.0f; m.Position.Y = 50.0f; m.Scale.X = 2.0f; m.Scale.Y = 0.5f;
