    V zero = { 0, 0, 0 };
    m.TailPos = zero; m.Dust = zero; m.TargetPos = zero;
    m.targetAlive = true; m.dustAlive = true; m.animDone = false;
    m.owner = zero; V t = { 3.0f, 0.0f, 0.0f }; m.target = t; V f = { 0, 1, 0 }; m.forward = f;
