    a.looping = false;
    a.finished = true;
    m.stateName = "HOVER_UNKNOWN";    // resolves to DEFAULT: not queued, but becomes current
    Update(m, a);
    ok = ok && m.queue.empty() && m.currentName == "HOVER_UNKNOWN";
