    while (ParentClass->SheriffState == SHERIFF_STATE_3) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating()) return;
        DoSuspicious();
    }
    if (IsActiveThreadTerminating()) return;
    if (ParentClass->SheriffState == SHERIFF_STATE_2) {
        if (IsActiveThreadTerminating()) return;
